-- Idempotent PostgreSQL script for Payment Module
-- Run manually against pos_db; never invoked at application startup.
BEGIN;
SET LOCAL lock_timeout = '10s';

DO $$
BEGIN
    IF current_database() <> 'pos_db' THEN
        RAISE EXCEPTION 'PaymentModule.sql must run against pos_db';
    END IF;
END $$;

CREATE TABLE IF NOT EXISTS "Orders" (
    "OrderId" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "OrderNumber" VARCHAR(30) UNIQUE NOT NULL,
    "BranchId" INT NOT NULL,
    "OutletId" INT NOT NULL,
    "CashierId" VARCHAR(450) NOT NULL,
    "ShiftId" BIGINT NULL,
    "OrderType" VARCHAR(20) NOT NULL,
    "OrderStatus" VARCHAR(20) NOT NULL,
    "PaymentStatus" VARCHAR(20) NOT NULL,
    "Subtotal" NUMERIC(18,2) NOT NULL,
    "DiscountAmount" NUMERIC(18,2) NOT NULL DEFAULT 0.00,
    "TotalAmount" NUMERIC(18,2) NOT NULL,
    "CreatedAt" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "CK_Orders_OrderNumber" CHECK (length(btrim("OrderNumber")) > 0)
);

CREATE TABLE IF NOT EXISTS "OrderItems" (
    "OrderItemId" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "OrderId" BIGINT NOT NULL,
    "ProductId" INT NOT NULL,
    "ProductName" VARCHAR(200) NOT NULL,
    "Quantity" NUMERIC(18,3) NOT NULL,
    "BasePrice" NUMERIC(18,2) NOT NULL,
    "ModifierTotal" NUMERIC(18,2) NOT NULL DEFAULT 0.00,
    "UnitPrice" NUMERIC(18,2) NOT NULL,
    "LineTotal" NUMERIC(18,2) NOT NULL,
    CONSTRAINT "FK_OrderItems_Orders" FOREIGN KEY ("OrderId") REFERENCES "Orders"("OrderId") ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS "IX_OrderItems_OrderId" ON "OrderItems" ("OrderId");

CREATE TABLE IF NOT EXISTS "OrderItemModifiers" (
    "OrderItemModifierId" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "OrderItemId" BIGINT NOT NULL,
    "ModifierOptionId" INT NOT NULL,
    "ModifierName" VARCHAR(100) NOT NULL,
    "AdditionalPrice" NUMERIC(18,2) NOT NULL,
    CONSTRAINT "FK_OrderItemModifiers_OrderItems" FOREIGN KEY ("OrderItemId") REFERENCES "OrderItems"("OrderItemId") ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS "IX_OrderItemModifiers_OrderItemId" ON "OrderItemModifiers" ("OrderItemId");

CREATE TABLE IF NOT EXISTS "Payments" (
    "PaymentId" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "OrderId" BIGINT NOT NULL,
    "PaymentMethod" VARCHAR(30) NOT NULL,
    "Amount" NUMERIC(18,2) NOT NULL,
    "AmountTendered" NUMERIC(18,2) NOT NULL,
    "ChangeAmount" NUMERIC(18,2) NOT NULL,
    "PaymentStatus" VARCHAR(20) NOT NULL,
    "ReferenceNumber" VARCHAR(100) NULL,
    "ProcessedBy" VARCHAR(450) NOT NULL,
    "PaidAt" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "FK_Payments_Orders" FOREIGN KEY ("OrderId") REFERENCES "Orders"("OrderId") ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS "IX_Payments_OrderId" ON "Payments" ("OrderId");

COMMIT;
